\begin{ex}%[6H4N2]
\immini[thm]{
Trong các hình sau hình nào là hình thang cân, hình nào là hình thoi.
}{
\begin{tikzpicture}

% Hình a) - Trapezoid
\draw[thick] (0,0) -- (2,0) -- (2.5,1.5) -- (-0.5,1.5) -- cycle;
\node at (1, -0.5) {\textbf{a)}};

% Hình b) - Parallelogram
\draw[thick] (3,0) -- (5,0) -- (6,1.5) -- (4,1.5) -- cycle;
\node at (4.5, -0.5) {\textbf{b)}};

% Hình c) - Rectangle
\draw[thick] (7,0) -- (9,0) -- (9,1.5) -- (7,1.5) -- cycle;
\node at (8, -0.5) {\textbf{c)}};

% Hình d) - Rhombus
\draw[thick] (10,0.75) -- (11.5,0) -- (13,0.75) -- (11.5,1.5) -- cycle;
\node at (11.5, -0.5) {\textbf{d)}};

\end{tikzpicture}
}
\loigiai{
Dựa vào tính chất các cạnh bằng nhau và hai đường chéo bằng nhau của hình đều / hình vuông / hình chữ nhật / hình thoi / hình bình hành / hình thang cân, ta suy ra ngay kết quả: Hình thang cân là a) c)\\
Hình thoi là d).
}\end{ex}

\begin{ex}%[6H4N2]
