    % Parallelogram - b)
    \draw[thick] (3,0) -- (5,0) -- (6,1.5) -- (4,1.5) -- cycle;
    \node at (4.5, -0.5) {b)};

    % Rectangle - c)
    \draw[thick] (7,0) -- (9,0) -- (9,1.5) -- (7,1.5) -- cycle;
    \node at (8, -0.5) {c)};

    % Rhombus - d)
    \draw[thick] (10,0.75) -- (11.5,0) -- (13,0.75) -- (11.5,1.5) -- cycle;
    \node at (11.5, -0.5) {d)};

    \end{tikzpicture}
}
\loigiai{
Dựa vào tính chất các cạnh bằng nhau và hai đường chéo bằng nhau của hình đều / hình vuông / hình chữ nhật / hình thoi / hình bình hành / hình thang cân, ta suy ra ngay kết quả: Hình chữ nhật là c)\\
Hình bình hành là c) b) d).
}\end{ex}
